// ── Auth check ──
const auth = $('Auth Lookup').item.json;
if (!auth.home_scope || auth.home_scope === '__UNAUTHORIZED__') {
  return [{ json: { valid: false, error: 'Unauthorized: invalid API key' } }];
}
const homeScope = auth.home_scope;
const allowedScopes = Array.isArray(auth.allowed_scopes) ? auth.allowed_scopes : [];
const readScopes = [homeScope, ...allowedScopes];

const body = $('Extract Key').item.json.body;

const query = body.query || null;
const category = body.category || null;
const tags = body.tags || null;
const compact = body.compact !== false;
let limit = parseInt(body.limit) || 10;
if (limit < 1) limit = 1;
if (limit > 50) limit = 50;

function esc(val) {
  if (val === null || val === undefined) return 'NULL';
  return "'" + String(val).replace(/'/g, "''") + "'";
}

function escArray(arr) {
  if (!Array.isArray(arr) || arr.length === 0) return "'{}'";
  const inner = arr.map(t => '"' + String(t).replace(/"/g, '\\"').replace(/'/g, "''") + '"').join(',');
  return "'{" + inner + "}'";
}

// Build dynamic WHERE clauses
const conditions = [];
let hasFulltext = false;
let selectExtra = '';

// Scope filter (always applied)
conditions.push(`scope IN (${readScopes.map(s => esc(s)).join(', ')})`);

if (query && typeof query === 'string' && query.trim() !== '') {
  hasFulltext = true;
  conditions.push(`to_tsvector('german', coalesce(title, '') || ' ' || content) @@ plainto_tsquery('german', ${esc(query.trim())})`);
  selectExtra = `, ts_rank(to_tsvector('german', coalesce(title, '') || ' ' || content), plainto_tsquery('german', ${esc(query.trim())})) AS relevance`;
}

if (category && typeof category === 'string' && category.trim() !== '') {
  conditions.push(`category = ${esc(category.trim())}`);
}

if (tags && Array.isArray(tags) && tags.length > 0) {
  conditions.push(`tags && ${escArray(tags)}`);
}

const whereClause = conditions.length > 0 ? 'WHERE ' + conditions.join(' AND ') : '';
const orderClause = hasFulltext ? 'ORDER BY relevance DESC' : 'ORDER BY updated_at DESC';

const selectFields = compact
  ? `id, category, tags, title, scope, LEFT(content, 200) AS content_preview, length(content) AS content_length, updated_at`
  : `id, category, tags, title, scope, content, metadata, created_at, updated_at`;

const sql = `SELECT ${selectFields}${selectExtra} FROM context_blocks ${whereClause} ${orderClause} LIMIT ${limit}`;

return [{ json: { valid: true, query: sql, compact: compact, hasFulltext: hasFulltext, searchQuery: query, searchCategory: category, searchTags: tags, searchLimit: limit } }];

const items = $input.all();
const searchMeta = $('Build Search Query').item.json;

// Collect all result rows
const results = items.filter(item => item.json && item.json.id).map(item => item.json);

return [{ json: { 
  success: true, 
  count: results.length, 
  compact: searchMeta.compact,
  filters: {
    query: searchMeta.searchQuery || null,
    category: searchMeta.searchCategory || null,
    tags: searchMeta.searchTags || null,
    limit: searchMeta.searchLimit
  },
  results: results 
} }];

